-- Hermes conformance seed, growth step 0 of 2: schema plus the first half of the
-- rows. One SQL statement per line (see conformance_test.go); '--' lines and
-- blank lines are skipped. Hand-written and fully synthetic, no real user data,
-- fixed UTC timestamps (2026-01-02T03:04:05Z = 1767323045).
CREATE TABLE sessions (id TEXT PRIMARY KEY, parent_session_id TEXT, model TEXT, billing_provider TEXT, billing_base_url TEXT, cwd TEXT, git_repo_root TEXT, title TEXT, started_at REAL, ended_at REAL, last_activity_at REAL, input_tokens INTEGER, output_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, reasoning_tokens INTEGER, estimated_cost_usd REAL, actual_cost_usd REAL, title_source TEXT, cost_source TEXT);
CREATE TABLE session_model_usage (session_id TEXT NOT NULL, model TEXT NOT NULL, billing_provider TEXT, billing_base_url TEXT, task TEXT, api_call_count INTEGER, input_tokens INTEGER, output_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, reasoning_tokens INTEGER, estimated_cost_usd REAL, actual_cost_usd REAL, first_seen REAL, last_seen REAL, PRIMARY KEY (session_id, model));
CREATE TABLE messages (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT, timestamp REAL, reasoning_content TEXT, compacted INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1);
